CREATE OR REPLACE FUNCTION public.get_public_business_hours(p_business_slug text DEFAULT NULL) RETURNS TABLE(weekday smallint,opens_at time,closes_at time) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ WITH business AS(SELECT public.resolve_booking_business(p_business_slug) id), active AS(SELECT p.id,p.business_id FROM public.professionals p JOIN business b ON p.business_id=b.id WHERE p.is_active), ranges AS(SELECT h.weekday,h.opens_at,h.closes_at FROM public.professional_hours h JOIN active a ON a.id=h.professional_id AND a.business_id=h.business_id UNION SELECT h.weekday,h.opens_at,h.closes_at FROM public.business_hours h JOIN business b ON b.id=h.business_id WHERE h.is_active AND (NOT EXISTS(SELECT 1 FROM active) OR EXISTS(SELECT 1 FROM active a WHERE NOT EXISTS(SELECT 1 FROM public.professional_hours ph WHERE ph.professional_id=a.id AND ph.business_id=a.business_id)))) SELECT DISTINCT r.weekday,r.opens_at,r.closes_at FROM ranges r ORDER BY r.weekday,r.opens_at; $$; COMMENT ON FUNCTION public.get_public_business_hours(text) IS 'Intentionally public: weekly opening ranges derived from active professionals, scoped by business slug. No private data.';